package org.eclipse.rdf4j.sail.lmdb.benchmark;

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.benchmark.common.ThemeQueryCatalog;
import org.eclipse.rdf4j.benchmark.rio.util.ThemeDataSetGenerator.Theme;
import org.eclipse.rdf4j.sail.lmdb.benchmark.FoafCliqueQueryCatalog.QueryScenario;

/**
 * The fixed query corpus of the three-regime parity harness (ExecPlan: {@code .agent/three-tier-parity-execplan.md},
 * Milestone 0). One enum constant per matrix row; the constant name is also the name of the {@code @Benchmark} method
 * in {@link ThreeTierParityBenchmark}, so a JMH result row and a census row for the same shape line up by name.
 *
 * <p>
 * Three datasets back the corpus, described by {@link Dataset}. A cell only ever touches the one dataset it declares,
 * so a run filtered to (say) the FOAF cells never opens the multi-gigabyte theme store.
 *
 * <p>
 * The corpus is deliberately broad rather than deep: it spans the shapes each of the three regimes claims to serve
 * (point lookups, scans, aggregates, stars, chains, cycles, paths, semijoins, OPTIONAL/MINUS/EXISTS, correlated
 * fragments) plus the slowest real-world theme queries, because the plan's acceptance rule is per-cell — a single
 * inverted cell fails it.
 */
public enum ThreeTierParityCorpus {

	// --- Adjacency-tier shapes over the FOAF clique store (Kuzu parity survey shapes) ---------------------------

	FULL_PREDICATE_SCAN("fullPredicateScan", Dataset.FOAF,
			"SELECT ?s ?o WHERE { ?s foaf:knows ?o }"),
	DISTINCT_SUBJECTS("distinctSubjects", Dataset.FOAF,
			"SELECT DISTINCT ?s WHERE { ?s foaf:knows ?o }"),
	COUNT_ONE_PREDICATE("countOnePredicate", Dataset.FOAF,
			"SELECT (COUNT(*) AS ?count) WHERE { ?s foaf:knows ?o }"),
	DEGREE_PER_SUBJECT("degreePerSubject", Dataset.FOAF,
			"SELECT ?s (COUNT(?o) AS ?d) WHERE { ?s foaf:knows ?o } GROUP BY ?s"),
	PREDICATE_HISTOGRAM("predicateHistogram", Dataset.FOAF,
			"SELECT ?p (COUNT(*) AS ?count) WHERE { ?s ?p ?o } GROUP BY ?p"),
	POINT_LOOKUP_OUT("pointLookupOut", Dataset.FOAF,
			"SELECT ?o WHERE { " + FoafData.SEED_PERSON + " foaf:knows ?o }"),
	POINT_LOOKUP_IN("pointLookupIn", Dataset.FOAF,
			"SELECT ?s WHERE { ?s foaf:knows " + FoafData.SEED_PERSON + " }"),
	DOUBLY_BOUND_PROBE("doublyBoundProbe", Dataset.FOAF,
			"SELECT * WHERE { " + FoafData.SEED_PERSON + " foaf:knows " + FoafData.SEED_TARGET + " }"),
	NODE_EDGE_DUMP("nodeEdgeDump", Dataset.FOAF,
			"SELECT ?p ?o WHERE { " + FoafData.SEED_PERSON + " ?p ?o }"),
	TWO_HOP_FROM_SEED("twoHopFromSeed", Dataset.FOAF,
			"SELECT ?o WHERE { " + FoafData.SEED_PERSON + " foaf:knows ?m . ?m foaf:knows ?o }"),
	PATH_REACHABILITY("pathReachability", Dataset.FOAF,
			"SELECT ?o WHERE { " + FoafData.SEED_PERSON + " foaf:knows+ ?o }"),
	SELECTIVE_SIP_CHAIN("selectiveSipChain", Dataset.FOAF,
			"SELECT ?s ?leaf WHERE { ?s exshape:root ?middle . ?middle exshape:selective ?value . "
					+ "?value exshape:selectiveLeaf ?leaf }"),
	DENSE_SIP_CHAIN("denseSipChain", Dataset.FOAF,
			"SELECT ?s ?leaf WHERE { ?s exshape:root ?middle . ?middle exshape:dense ?value . "
					+ "?value exshape:denseLeaf ?leaf }"),
	STAR_JOIN("starJoin", Dataset.FOAF,
			"SELECT ?f ?c ?a WHERE { ?p foaf:knows ?f . ?p foaf:based_near ?c . ?p foaf:age ?a }"),
	CHAIN_JOIN_OPEN("chainJoinOpen", Dataset.FOAF,
			"SELECT ?p ?label WHERE { ?p foaf:based_near ?c . ?c rdfs:label ?label }"),
	OBJECT_OBJECT_JOIN("objectObjectJoin", Dataset.FOAF,
			"SELECT ?a ?b WHERE { VALUES ?city { excity:oslo } ?a foaf:based_near ?city . "
					+ "?b foaf:based_near ?city }"),
	VALUES_BATCH_LOOKUP("valuesBatchLookup", Dataset.FOAF,
			"SELECT ?s ?o WHERE { VALUES ?s { " + FoafData.seedBatch(8) + " } ?s foaf:knows ?o }"),
	ORDERED_NEIGHBORS("orderedNeighbors", Dataset.FOAF,
			"SELECT ?o WHERE { " + FoafData.SEED_PERSON + " foaf:knows ?o } ORDER BY ?o"),
	ALL_PREDICATES("allPredicates", Dataset.FOAF,
			"SELECT DISTINCT ?p WHERE { ?s ?p ?o }"),

	// --- Node-to-predicate projection shapes (ExecPlan .agent/node-predicate-projection-execplan.md, A6) --------
	//
	// The pre-existing nodeEdgeDump cell above cannot measure this work: it dumps one seed node, so all three
	// regimes finish in about 17 microseconds and tie inside their own error bars. These five cells give the shape
	// enough headroom to show a difference, and the last of them is deliberately a control rather than a target.

	/**
	 * The flagship. A type lookup joined to an unbound-predicate dump of every matching instance, grouped by type and
	 * predicate — the shape a schema-discovery or profiling tool runs, and the one where the projection replaces "try
	 * every predicate in the store at every node" with one row read per node.
	 *
	 * <p>
	 * The classes are supplied as a {@code VALUES} list rather than left as a free {@code ?s a ?t}. That is not
	 * cosmetic: with both sides unbound the planner roots the whole query on {@code ?s ?p ?o}, evaluates it as a scan
	 * with no subject in hand, and the projection is never consulted at all — the first draft of this cell measured
	 * exactly that and recorded zero adjacency engagement in every regime. Naming the classes makes the type lookup the
	 * smaller side, which is what puts a bound node in front of the dump.
	 */
	CLASS_PREDICATE_MATRIX("classPredicateMatrix", Dataset.FOAF,
			"SELECT ?t ?p (COUNT(*) AS ?n) WHERE { VALUES ?t { foaf:Person foaf:Organization } "
					+ "?s a ?t . ?s ?p ?o } GROUP BY ?t ?p"),
	/** The same dump as {@code nodeEdgeDump} but over a batch of seeds, so the per-node cost is actually measurable. */
	REPEATED_NODE_DUMP("repeatedNodeDump", Dataset.FOAF,
			"SELECT ?s ?p ?o WHERE { VALUES ?s { " + FoafData.seedBatch(64) + " } ?s ?p ?o }"),
	/** A variable-predicate dump driven by a correlated outer row rather than by a constant key. */
	VARIABLE_PREDICATE_JOIN("variablePredicateJoin", Dataset.FOAF,
			"SELECT ?p ?o WHERE { " + FoafData.SEED_PERSON + " foaf:knows ?m . ?m ?p ?o }"),
	/** The reverse direction, {@code ?s ?p <o>}; serves only once the incoming planes are switched on (Gate D). */
	INCOMING_EDGE_DUMP("incomingEdgeDump", Dataset.FOAF,
			"SELECT ?s ?p WHERE { ?s ?p " + FoafData.SEED_PERSON + " }"),
	/**
	 * A control, not a target, and worth stating plainly because an earlier draft of this work had it backwards. All
	 * three positions are unbound; the compiled enumerator requires a bound key; and a whole-projection root enumerator
	 * is out of scope because the projection deliberately exposes no key-domain accessor. This cell proves the
	 * projection causes no regression on a shape it does not serve, and its variable-predicate lowering count must stay
	 * at zero.
	 */
	OUT_DEGREE_HISTOGRAM("outDegreeHistogram", Dataset.FOAF,
			"SELECT ?s (COUNT(*) AS ?d) WHERE { ?s ?p ?o } GROUP BY ?s"),

	// --- Cyclic (worst-case-optimal) shapes, identical to FoafCliqueQueryBenchmark ------------------------------

	CYCLE3("cycle3", Dataset.FOAF, QueryScenario.CYCLE3),
	CYCLE4("cycle4", Dataset.FOAF, QueryScenario.CYCLE4),
	CYCLE5("cycle5", Dataset.FOAF, QueryScenario.CYCLE5),
	CYCLE3_COUNT_CITY_INTEREST("cycle3CountCityInterest", Dataset.FOAF, QueryScenario.CYCLE3_COUNT_CITY_INTEREST),
	CYCLE3_DISTINCT_CITY_ORDERED("cycle3DistinctCityOrdered", Dataset.FOAF,
			QueryScenario.CYCLE3_DISTINCT_CITY_ORDERED),
	CYCLE4_VALUES_FILTERED_ORDERED("cycle4ValuesFilteredOrdered", Dataset.FOAF,
			QueryScenario.CYCLE4_VALUES_FILTERED_ORDERED),
	CYCLE3_GROUPED_INTEREST("cycle3GroupedInterest", Dataset.FOAF, QueryScenario.CYCLE3_GROUPED_INTEREST),
	CYCLE5_VALUES_COUNT_MAILBOX_HOMEPAGE("cycle5ValuesCountMailboxHomepage", Dataset.FOAF,
			QueryScenario.CYCLE5_VALUES_COUNT_MAILBOX_HOMEPAGE),
	CYCLE5_VALUES_DISTINCT_MAILBOX_ORDERED("cycle5ValuesDistinctMailboxOrdered", Dataset.FOAF,
			QueryScenario.CYCLE5_VALUES_DISTINCT_MAILBOX_ORDERED),

	// --- Operator families that are adjacency-blind today (Milestones 2 and 5 target these) --------------------

	OPTIONAL_HEAVY("optionalHeavy", Dataset.FOAF,
			"SELECT ?a ?b ?nick WHERE { ?a foaf:knows ?b . "
					+ "OPTIONAL { ?b foaf:nick ?nick . ?b foaf:homepage ?home } }"),
	MINUS_SHAPE("minusShape", Dataset.FOAF,
			"SELECT ?a ?b WHERE { ?a foaf:knows ?b . MINUS { ?b foaf:based_near excity:oslo } }"),
	EXISTS_SEMIJOIN("existsSemijoin", Dataset.FOAF,
			"SELECT ?a ?b WHERE { ?a foaf:knows ?b . "
					+ "FILTER EXISTS { ?b foaf:knows " + FoafData.SEED_PERSON + " } }"),
	SEQUENCE_PATH("sequencePath", Dataset.FOAF,
			"SELECT ?a ?city WHERE { ?a foaf:knows/foaf:based_near ?city }"),

	// --- Correlated-entry shapes, identical to CorrelatedBenchmark ---------------------------------------------

	OUTER_ACCUMULATE("outerAccumulate", Dataset.CORRELATED,
			"SELECT ?outer ?value WHERE { ?outer <" + CorrelatedData.NS + "seed> ?seed . "
					+ "OPTIONAL { ?seed <" + CorrelatedData.NS + "inner> ?leaf . "
					+ "?leaf <" + CorrelatedData.NS + "payload> ?value } }"),
	CORRELATED_COUNT("correlatedCount", Dataset.CORRELATED,
			"SELECT (COUNT(*) AS ?count) WHERE { ?outer <" + CorrelatedData.NS + "seed> ?seed . "
					+ "OPTIONAL { ?seed <" + CorrelatedData.NS + "inner> ?leaf . "
					+ "?leaf <" + CorrelatedData.NS + "payload> ?value } }"),
	PATH_UNDER_JOIN("pathUnderJoin", Dataset.CORRELATED,
			"SELECT ?outer ?end WHERE { ?outer <" + CorrelatedData.NS + "pathStart> ?start . "
					+ "?start <" + CorrelatedData.NS + "next>+ ?end }"),

	// --- Theme-corpus representatives: the slowest ANALYTICS / HIGHLY_CONNECTED / ENGINEERING cells -------------

	THEME_ANALYTICS_Q5("themeAnalyticsQ5", Theme.ANALYTICS, 5),
	THEME_ANALYTICS_Q8("themeAnalyticsQ8", Theme.ANALYTICS, 8),
	THEME_ANALYTICS_Q9("themeAnalyticsQ9", Theme.ANALYTICS, 9),
	THEME_HIGHLY_CONNECTED_Q1("themeHighlyConnectedQ1", Theme.HIGHLY_CONNECTED, 1),
	THEME_HIGHLY_CONNECTED_Q4("themeHighlyConnectedQ4", Theme.HIGHLY_CONNECTED, 4),
	THEME_ENGINEERING_Q1("themeEngineeringQ1", Theme.ENGINEERING, 1);

	/** Which store a cell runs against. Each dataset is built at most once per JVM, on first use. */
	public enum Dataset {
		/**
		 * The 5000-person FOAF clique store of {@link FoafCliqueQueryBenchmark} plus the selective/dense chain shapes
		 * of {@link AdjacencyQueryShapeBenchmark}. Generated into a temporary directory.
		 */
		FOAF,
		/**
		 * The correlated-entry store of {@link CorrelatedBenchmark}: 1000 outer rows, each seeding a 128-leaf inner
		 * fragment, plus 100 path chains of depth 32. Generated into a temporary directory.
		 */
		CORRELATED,
		/**
		 * The fixed multi-theme benchmark store under {@code core/sail/lmdb/target/lmdb-theme-query-benchmark/complete}
		 * that {@link ThemeQueryBenchmark} loads. It is reused read-only and never rebuilt by this harness.
		 */
		THEME
	}

	private final String benchmarkMethodName;
	private final Dataset dataset;
	private final String query;

	ThreeTierParityCorpus(String benchmarkMethodName, Dataset dataset, String query) {
		this.benchmarkMethodName = benchmarkMethodName;
		this.dataset = dataset;
		this.query = FoafData.PREFIXES + query;
	}

	ThreeTierParityCorpus(String benchmarkMethodName, Dataset dataset, QueryScenario scenario) {
		this.benchmarkMethodName = benchmarkMethodName;
		this.dataset = dataset;
		this.query = scenario.query();
	}

	ThreeTierParityCorpus(String benchmarkMethodName, Theme theme, int queryIndex) {
		this.benchmarkMethodName = benchmarkMethodName;
		this.dataset = Dataset.THEME;
		this.query = ThemeQueryCatalog.queryFor(theme, queryIndex);
	}

	/** Name of the {@code @Benchmark} method that measures this cell; also the census row label. */
	public String benchmarkMethodName() {
		return benchmarkMethodName;
	}

	public Dataset dataset() {
		return dataset;
	}

	public String query() {
		return query;
	}

	public static List<ThreeTierParityCorpus> of(Dataset dataset) {
		return Arrays.stream(values()).filter(entry -> entry.dataset == dataset).collect(Collectors.toList());
	}

	/**
	 * Resolves the cell measured by a JMH benchmark identifier such as
	 * {@code org.eclipse.rdf4j.sail.lmdb.benchmark.ThreeTierParityBenchmark.cycle3}. Lets the benchmark prepare exactly
	 * the cell it is about to measure in {@code @Setup}, instead of paying preparation inside a measured iteration.
	 */
	public static ThreeTierParityCorpus byBenchmarkMethod(String benchmarkIdentifier) {
		String methodName = benchmarkIdentifier.substring(benchmarkIdentifier.lastIndexOf('.') + 1);
		for (ThreeTierParityCorpus entry : values()) {
			if (entry.benchmarkMethodName.equals(methodName)) {
				return entry;
			}
		}
		throw new IllegalArgumentException("No three-tier parity corpus cell is named " + methodName
				+ "; every @Benchmark method in ThreeTierParityBenchmark must match a corpus constant");
	}

	/** Constants for the FOAF store, duplicated from the sibling benchmarks so this harness stays self-contained. */
	static final class FoafData {

		static final String PERSON_NAMESPACE = "http://example.org/foaf/person/";
		static final String SHAPE_NAMESPACE = "urn:rdf4j:adjacency-shape:";
		static final String SEED_PERSON = "<" + PERSON_NAMESPACE + "0>";
		static final String SEED_TARGET = "<" + PERSON_NAMESPACE + "1>";

		static final String PREFIXES = "PREFIX foaf: <http://xmlns.com/foaf/0.1/>\n"
				+ "PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>\n"
				+ "PREFIX excity: <" + FoafCliqueQueryCatalog.CITY_NAMESPACE + ">\n"
				+ "PREFIX exinterest: <" + FoafCliqueQueryCatalog.INTEREST_NAMESPACE + ">\n"
				+ "PREFIX exrole: <" + FoafCliqueQueryCatalog.ROLE_NAMESPACE + ">\n"
				+ "PREFIX exshape: <" + SHAPE_NAMESPACE + ">\n";

		private FoafData() {
		}

		static String seedBatch(int count) {
			StringBuilder builder = new StringBuilder();
			for (int person = 1; person <= count; person++) {
				builder.append('<').append(PERSON_NAMESPACE).append(person).append("> ");
			}
			return builder.toString().trim();
		}
	}

	/** Constants for the correlated store, matching {@link CorrelatedBenchmark}'s namespace and shape. */
	static final class CorrelatedData {

		static final String NS = "http://example.com/correlated/";
		static final int OUTER_ROWS = 1000;
		static final int INNER_FAN_OUT = 128;
		static final int DISTINCT_PATH_STARTS = 100;
		static final int PATH_DEPTH = 32;

		private CorrelatedData() {
		}
	}
}
